def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != background}

    candidates = []
    for color in colors:
        # Prefix sums of occurrences of this color.
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )

        for r0 in range(h):
            for r1 in range(r0 + 1, h + 1):
                for c0 in range(w):
                    for c1 in range(c0 + 1, w + 1):
                        area = (r1 - r0) * (c1 - c0)
                        if area < 6:
                            continue
                        count = p[r1][c1] - p[r0][c1] - p[r1][c0] + p[r0][c0]
                        if count >= 4 and count * 100 >= area * 65:
                            candidates.append(
                                (area, count, color, r0, r1, c0, c1)
                            )

    # Prefer the largest plausible rectangles, suppressing smaller candidates
    # that are just overlapping portions of the same object.
    candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
    chosen = []
    for area, count, color, r0, r1, c0, c1 in candidates:
        duplicate = False
        for _, _, old_color, a0, a1, b0, b1 in chosen:
            if color != old_color:
                continue
            overlap = max(0, min(r1, a1) - max(r0, a0)) * max(
                0, min(c1, b1) - max(c0, b0)
            )
            if overlap * 2 >= min(area, (a1 - a0) * (b1 - b0)):
                duplicate = True
                break
        if not duplicate:
            chosen.append((area, count, color, r0, r1, c0, c1))

    out = [[background] * w for _ in range(h)]
    for _, _, color, r0, r1, c0, c1 in chosen:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
